import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { Navigate } from 'react-router-dom';
import AddProductModal from '../components/AddProductModal';
import ProductCard from '../components/ProductCard';
import { PlusIcon, PencilIcon, TrashIcon, CheckIcon, XMarkIcon } from '@heroicons/react/24/outline';
import axios from 'axios';

const FarmerDashboard = () => {
  const { user, token } = useAuth();
  const [products, setProducts] = useState([]);
  const [pendingOrders, setPendingOrders] = useState([]);
  const [allOrders, setAllOrders] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [confirmingOrderId, setConfirmingOrderId] = useState(null);
  const [rejectingOrderId, setRejectingOrderId] = useState(null);

  // Normalize ID (Handles MongoDB _id or standard id)
  const farmerId = user?._id || user?.id;

  const fixedPrices = {
    tomato: 40, onion: 30, potato: 25, carrot: 35, cabbage: 20,
    cauliflower: 45, spinach: 50, broccoli: 60, cucumber: 30,
    capsicum: 55, eggplant: 35, okra: 40
  };

  const loadDashboardData = useCallback(async () => {
    if (!farmerId || !token) return;

    try {
      const config = {
        headers: { Authorization: `Bearer ${token}` }
      };

      // Fetch Products and Orders in parallel for speed
      const [prodRes, ordersRes] = await Promise.all([
        axios.get(`http://localhost:3000/api/products/farmer/${farmerId}`, config),
        axios.get(`http://localhost:3000/api/orders/farmer/${farmerId}`, config)
      ]);

      setProducts(prodRes.data);
      setAllOrders(ordersRes.data);
      setPendingOrders(ordersRes.data.filter(order => order.status === 'pending'));
    } catch (error) {
      console.error('Dashboard Load Error:', error);
    } finally {
      setLoading(false);
    }
  }, [farmerId, token]);

  useEffect(() => {
    loadDashboardData();
  }, [loadDashboardData]);

  const calculateRevenue = () => {
    return allOrders
      .filter(o => ['confirmed', 'shipped', 'delivered'].includes(o.status))
      .reduce((total, order) => total + (order.totalPrice || 0), 0);
  };

  const handleConfirmOrder = async (orderId) => {
    setConfirmingOrderId(orderId);
    try {
      await axios.put(`http://localhost:3000/api/orders/${orderId}/confirm`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      await loadDashboardData(); // Refresh stats from DB
    } catch (error) {
      alert('Failed to confirm order.');
    } finally {
      setConfirmingOrderId(null);
    }
  };

  const handleRejectOrder = async (orderId) => {
    const reason = prompt('Reason for rejection?', 'Out of stock');
    if (!reason) return;
    setRejectingOrderId(orderId);
    try {
      await axios.put(`http://localhost:3000/api/orders/${orderId}/cancel`, { notes: reason }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      await loadDashboardData();
    } catch (error) {
      alert('Failed to reject order.');
    } finally {
      setRejectingOrderId(null);
    }
  };

  if (!user || user.userType !== 'farmer') return <Navigate to="/login" />;

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Welcome, {user.name}! 🚜</h1>
          <p className="text-gray-600">Real-time business overview</p>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <StatCard title="Total Products" value={products.length} icon="🥬" color="bg-green-100" />
          <StatCard title="Pending Orders" value={pendingOrders.length} icon="⏳" color="bg-yellow-100" textColor="text-yellow-600" />
          <StatCard title="Total Orders" value={allOrders.length} icon="📦" color="bg-blue-100" />
          <StatCard title="Revenue" value={`₹${calculateRevenue()}`} icon="💰" color="bg-green-100" />
        </div>

        {/* Pending Orders Section */}
        <div className="mb-12">
          <h2 className="text-xl font-bold mb-4">Pending Requests</h2>
          {pendingOrders.length === 0 ? (
            <div className="bg-white p-6 rounded-lg text-center text-gray-500">No new orders yet.</div>
          ) : (
            <div className="space-y-4">
              {pendingOrders.map(order => (
                <div key={order._id} className="bg-white p-6 rounded-lg shadow-sm border-l-4 border-yellow-400 flex justify-between items-center">
                  <div>
                    <p className="font-bold text-lg">{order.customerName}</p>
                    <p className="text-sm text-gray-500">{order.items.map(i => `${i.name} (${i.quantity}kg)`).join(', ')}</p>
                    <p className="font-semibold text-green-600 mt-1">Total: ₹{order.totalPrice}</p>
                  </div>
                  <div className="flex space-x-2">
                    <button 
                      onClick={() => handleConfirmOrder(order._id)}
                      disabled={confirmingOrderId === order._id}
                      className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700 flex items-center"
                    >
                      {confirmingOrderId === order._id ? '...' : <CheckIcon className="w-5 h-5 mr-1" />} Confirm
                    </button>
                    <button 
                      onClick={() => handleRejectOrder(order._id)}
                      className="bg-red-50 text-red-600 px-4 py-2 rounded-md hover:bg-red-100"
                    >
                      <XMarkIcon className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Products Section */}
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold">My Inventory</h2>
          <button onClick={() => setShowAddModal(true)} className="bg-green-600 text-white px-4 py-2 rounded-md flex items-center">
            <PlusIcon className="w-5 h-5 mr-1" /> Add Vegetable
          </button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {products.map(product => (
            <ProductCard key={product._id} product={product} showAddToCart={false} />
          ))}
        </div>
      </div>

      {showAddModal && (
        <AddProductModal 
          isOpen={showAddModal} 
          onClose={() => setShowAddModal(false)} 
          onSubmit={loadDashboardData} 
          fixedPrices={fixedPrices} 
        />
      )}
    </div>
  );
};

const StatCard = ({ title, value, icon, color, textColor = "text-gray-900" }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
    <div className="flex items-center">
      <div className={`p-3 ${color} rounded-lg text-2xl`}>{icon}</div>
      <div className="ml-4">
        <p className="text-sm text-gray-500 font-medium">{title}</p>
        <p className={`text-2xl font-bold ${textColor}`}>{value}</p>
      </div>
    </div>
  </div>
);

export default FarmerDashboard;
